pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny gaps that are unlikely to accommodate future items (1..10)
    // We reward post_residual values that are either 0 (perfect fit) or >= 20 (high flexibility)
    let gap_penalty = if post > 0.0 && post < 20.0 {
        (20.0 - post).powi(2) * (1.0 + progress)
    } else {
        0.0
    };

    // If next_item_size is known, penalize bins that cannot fit the next item
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Reward bins that maintain a residual close to the global mean to consolidate fragmentation
    let fragmentation_penalty = (post - mean_residual).abs() * 0.5;

    // Discourage opening new bins early in the stream unless necessary
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            50.0 * (1.0 - progress)
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Base score is post_residual; lower is better (Best Fit principle)
    // We favor smaller post_residuals but add penalties to avoid "dead" gaps
    let score = post + gap_penalty + lookahead_penalty + fragmentation_penalty + new_bin_penalty;

    score
}
